import{_ as e,o as i,c as o,a2 as l}from"./chunks/framework.Bi3alPNc.js";const b=JSON.parse('{"title":"参与共创","description":"WorkBuddy 的能力、界面和使用方式会持续变化。这本蓝皮书希望由真实使用者共同维护：不仅纠正事实，也不断补充可复现的任务、失败经验和团队方法。 如果你已经用 WorkBuddy 跑通了一项真实任务，推荐优先提交到社区案例集…","frontmatter":{},"headers":[],"relativePath":"community/contributing.md","filePath":"community/contributing.md","lastUpdated":1785728626000}'),r={name:"community/contributing.md"};function t(s,a,n,d,u,c){return i(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="参与共创" tabindex="-1">参与共创 <a class="header-anchor" href="#参与共创" aria-label="Permalink to &quot;参与共创&quot;">​</a></h1><p>WorkBuddy 的能力、界面和使用方式会持续变化。这本蓝皮书希望由真实使用者共同维护：不仅纠正事实，也不断补充可复现的任务、失败经验和团队方法。</p><h2 id="可以贡献什么" tabindex="-1">可以贡献什么 <a class="header-anchor" href="#可以贡献什么" aria-label="Permalink to &quot;可以贡献什么&quot;">​</a></h2><ul><li>修正错别字、失效链接、过时界面和不准确表述。</li><li>补充一个真实、可复现的 WorkBuddy 案例。</li><li>为现有案例增加输入、输出、验收标准和失败处理。</li><li>补充岗位或行业工作流。</li><li>改进截图、图表、导航和无障碍体验。</li></ul><h2 id="提交社区-case" tabindex="-1">提交社区 Case <a class="header-anchor" href="#提交社区-case" aria-label="Permalink to &quot;提交社区 Case&quot;">​</a></h2><p>如果你已经用 WorkBuddy 跑通了一项真实任务，推荐优先提交到<a href="/workbuddy/cases/">社区案例集</a>。每个 Case 需要说明使用场景、使用的 Skills、在 WorkBuddy 中的操作、最终效果和验收标准。</p><p>请先阅读<a href="/workbuddy/community/case-contributing">Case 投稿指南</a>。PR 合并后，案例会自动显示在网站的案例集合页；经过进一步复现和编辑的经典任务，未来可能进入蓝皮书正文。</p><h2 id="最轻量的方式-提交-issue" tabindex="-1">最轻量的方式：提交 Issue <a class="header-anchor" href="#最轻量的方式-提交-issue" aria-label="Permalink to &quot;最轻量的方式：提交 Issue&quot;">​</a></h2><p>如果暂时不想修改文件，可以在 <a href="https://github.com/yun520-1/workbuddy/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 中说明：</p><ol><li>哪一页需要调整。</li><li>现在的问题是什么。</li><li>建议怎样修改。</li><li>如果涉及产品事实，请附上来源或截图。</li></ol><h2 id="直接修改内容" tabindex="-1">直接修改内容 <a class="header-anchor" href="#直接修改内容" aria-label="Permalink to &quot;直接修改内容&quot;">​</a></h2><ol><li>Fork 或克隆仓库。</li><li>找到 <code>docs/bluebook/</code> 下对应章节的 <code>index.md</code>。</li><li>修改内容或在同目录的 <code>assets/</code> 中补充素材。</li><li>本地运行 <code>npm install</code> 和 <code>npm run docs:build</code>。</li><li>提交 Pull Request，并说明改动、原因和验证方式。</li></ol><p>完整规范见仓库根目录的 <a href="https://github.com/yun520-1/workbuddy/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>。</p><h2 id="内容原则" tabindex="-1">内容原则 <a class="header-anchor" href="#内容原则" aria-label="Permalink to &quot;内容原则&quot;">​</a></h2><ul><li><strong>真实任务优先</strong>：说明输入、步骤、交付物和验收方式。</li><li><strong>事实与经验分开</strong>：产品事实尽量附来源；个人经验说明适用条件。</li><li><strong>对新手友好</strong>：不要假设读者知道工具、权限和术语。</li><li><strong>安全边界清晰</strong>：涉及文件、账号、密钥、发布和外部操作时说明风险。</li><li><strong>尊重隐私与版权</strong>：不要提交密钥、个人数据或无权公开的资料。</li></ul>',15)])])}const m=e(r,[["render",t]]);export{b as __pageData,m as default};
